import{_ as t,o as a,c as _,a4 as s}from"./chunks/framework.a8fFxTj0.js";const i=JSON.parse('{"title":"2025年首届智慧农业创新大赛：33LJ531-800叁拾叁温室搬运机器人","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"2025年首届智慧农业创新大赛：33LJ531-800叁拾叁温室搬运机器人","date":"2026-03-11T00:00:00.000Z","source":"农业农村部智慧农业-地方实践","category":"cases","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/dfsj/202603/t20260311_6482170.htm","summary":"一、团队介绍\\n江苏叁拾叁智慧农业有限公司成立于2013年,是一家致力于农业生产领域的少人化、无人化技术的高新技术企业和国家级专精特新“小巨人”企业,已有专利53项、软著117项。从早期专注技术研发,到如今形成“软硬件一体化”全场景闭环能力,持续以技术创新推动农业智能化。从装备到系统,从数据到决策,以“技术研发+场景落地+生态协同”为核心模式,聚焦智慧农业全产业链。\\n二、装备亮点\\n一是双轮前驱设计。...\\n","contentHash":"3cdc683f87455a32212382febdffcccf","tags":["智慧农业","地方案例"]},"headers":[],"relativePath":"cases/2026-03-11-2025年首届智慧农业创新大赛-33LJ531-800叁拾叁温室搬运机器人.md","filePath":"cases/2026-03-11-2025年首届智慧农业创新大赛-33LJ531-800叁拾叁温室搬运机器人.md"}'),r={name:"cases/2026-03-11-2025年首届智慧农业创新大赛-33LJ531-800叁拾叁温室搬运机器人.md"};function n(o,e,l,c,p,d){return a(),_("div",null,[...e[0]||(e[0]=[s('<h1 id="_2025年首届智慧农业创新大赛-33lj531-800叁拾叁温室搬运机器人" tabindex="-1">2025年首届智慧农业创新大赛：33LJ531-800叁拾叁温室搬运机器人 <a class="header-anchor" href="#_2025年首届智慧农业创新大赛-33lj531-800叁拾叁温室搬运机器人" aria-label="Permalink to &quot;2025年首届智慧农业创新大赛：33LJ531-800叁拾叁温室搬运机器人&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/dfsj/202603/t20260311_6482170.htm" target="_blank" rel="noreferrer">农业农村部智慧农业-地方实践</a><br> 日期: 2026-03-11 摘要: 一、团队介绍 江苏叁拾叁智慧农业有限公司成立于2013年,是一家致力于农业生产领域的少人化、无人化技术的高新技术企业和国家级专精特新“小巨人”企业,已有专利53项、软著117项。从早期专注技术研发,到如今形成“软硬件一体化”全场景闭环能力,持续以技术创新推动农业智能化。从装备到系统,从数据到决策,以“技术研发+场景落地+生态协同”为核心模式,聚焦智慧农业全产业链。 二、装备亮点 一是双轮前驱设计。...</p></blockquote><p>江苏叁拾叁智慧农业有限公司成立于2013年,是一家致力于农业生产领域的少人化、无人化技术的高新技术企业和国家级专精特新“小巨人”企业,已有专利53项、软著117项。从早期专注技术研发,到如今形成“软硬件一体化”全场景闭环能力,持续以技术创新推动农业智能化。从装备到系统,从数据到决策,以“技术研发+场景落地+生态协同”为核心模式,聚焦智慧农业全产业链。</p><p>二、装备亮点</p><p>一是双轮前驱设计。在减少地面磨损、增大爬坡能力的基础上让车身结构更紧凑。二是原地旋转能力。可在温室种植期间的狭窄通道内或防草布铺设的通道内自由穿行。三是搭载多传感器融合导航系统。结合主动绕障算法,实现复杂环境下的精准避障与稳定行走。四是模块化挂载设计。可根据任务需求快速更换功能组件。</p><p>三、应用场景与成效</p><p>33LJ531-800叁拾叁温室搬运机器人专为现代化温室场景设计。在“丰收大地育苗温室”中,机器人已实现播种线至苗床间的全程自动化搬运,有效衔接各生产环节,构建智能化育苗生产线。实际应用表明,该设备显著提升了物流效率,降低了人工成本与育苗盘损伤率。</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/dfsj/202603/t20260311_6482170.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',8)])])}const h=t(r,[["render",n]]);export{i as __pageData,h as default};
